SELECT r.*, o.user_id AS userId, u.nickname AS userName, u.phone AS userPhone, d.name AS doctorName, i.name AS itemName FROM report_item r LEFT JOIN orders o ON r.order_id = o.id LEFT JOIN user u ON o.user_id = u.id LEFT JOIN doctor d ON r.doctor_id = d.id LEFT JOIN checkitem i ON r.item_id = i.id
AND (r.doctor_id = #{query.doctorId} OR r.doctor_id = 0)
AND r.doctor_id = #{query.doctorId}
AND r.order_id = #{query.orderId}
AND r.report_status = #{query.reportStatus}
AND (u.nickname LIKE CONCAT('%', #{query.patientKeyword}, '%') OR u.phone LIKE CONCAT('%', #{query.patientKeyword}, '%'))
ORDER BY r.create_time DESC

SELECT r.*, o.user_id AS userId, u.nickname AS userName, u.phone AS userPhone, o.patient_name AS patientName, o.patient_age AS patientAge, o.patient_gender AS patientGender, CASE o.patient_gender WHEN 0 THEN '女' WHEN 1 THEN '男' ELSE '未知' END AS patientGenderText, o.patient_phone AS patientPhone, d.name AS doctorName, i.name AS itemName FROM report_item r LEFT JOIN orders o ON r.order_id = o.id LEFT JOIN user u ON o.user_id = u.id LEFT JOIN doctor d ON r.doctor_id = d.id LEFT JOIN checkitem i ON r.item_id = i.id
AND (r.doctor_id = #{query.doctorId} OR r.doctor_id = 0)
AND r.doctor_id = #{query.doctorId}
AND r.order_id = #{query.orderId}
AND r.report_status = #{query.reportStatus}
AND (u.nickname LIKE CONCAT('%', #{query.patientKeyword}, '%') OR u.phone LIKE CONCAT('%', #{query.patientKeyword}, '%') OR o.patient_name LIKE CONCAT('%', #{query.patientKeyword}, '%') OR o.patient_phone LIKE CONCAT('%', #{query.patientKeyword}, '%'))
ORDER BY r.create_time DESC

SELECT r.*, o.user_id AS userId, u.nickname AS userName, u.phone AS userPhone, d.name AS doctorName, i.name AS itemName FROM report_item r LEFT JOIN orders o ON r.order_id = o.id LEFT JOIN user u ON o.user_id = u.id LEFT JOIN doctor d ON r.doctor_id = d.id LEFT JOIN checkitem i ON r.item_id = i.id
AND o.user_id = #{query.userId}
AND r.report_status = #{query.reportStatus}
ORDER BY r.create_time DESC
